What is the output of the following C code?

int arr[] = {10, 20, 30, 40, 50};
int *p = arr;
p++;
printf("%d", *(p + 2));

What is the output of the following C code?

void swap(int x, int *y) {
    int temp = x;
    x = *y;
    *y = temp;
}

int main() {
    int a = 5, b = 10;
    swap(a, &b);
    printf("%d %d", a, b);
    return 0;
}

What is the output of the following C code?

int func() {
    static int count = 0;
    count++;
    return count;
}

int main() {
    int x = func();
    func();
    x = func();
    printf("%d", x);
    return 0;
}

What is the output of the following C code?

int a = 10;
int *p = &a;
int **q = &p;
**q = 20;
printf("%d", a);

What is the output of the following C code?

int main() {
    int arr[] = {1, 2, 3, 4, 5};
    int *p = arr;
    printf("%d", *(p + 3) - *(p + 1));
    return 0;
}
